// Build Claude request from pipeline stats.
const stats = $input.first().json;

const systemPrompt = [
  'You are a sales analyst writing the weekly pipeline report for Underwings, a UAE cybersecurity services company (Abu Dhabi, launched 2026).',
  '',
  'Practitioners: Manoj (GRC + healthcare ADHICS), Nelson (offensive sec), Vinoth (network).',
  'Pipelines: 4=Cybersecurity Sales (one-offs), 5=Software Resale, 6=Subscriptions (PTaaS, Continuous Compliance).',
  'Stages on P4: New (id 13) -> MQL (14) -> Contacted (15) -> Discovery Booked (16) -> Scoping (17) -> Proposal Sent (18) -> Negotiation (19) -> Won (20) / Lost (21).',
  '',
  'You will be given JSON stats for the last 7 days. Write a tight HTML report (NO markdown, NO <html>/<head> tags, just body content) covering:',
  '<h2>Weekly pipeline report — {period start} to {period end}</h2>',
  '<h3>TL;DR</h3><p>Two sentences: total leads this week, biggest signal, and the single action you recommend.</p>',
  '<h3>Leads in (this week)</h3><p>Total + breakdown by source + by pipeline. Call out the dominant source.</p>',
  '<h3>AI scoring</h3><p>Average score + hot/nurture/low-fit split. If most leads are scoring under 40, say that\'s a quality problem and recommend tightening intake or improving ICP filters.</p>',
  '<h3>Pipeline shape (current snapshot)</h3><p>Where leads are sitting right now. Flag the biggest drop-off (the stage with high count vs the next stage with low count).</p>',
  '<h3>Won / Lost this week</h3><p>Counts + AED value won. If zero, say so plainly.</p>',
  '<h3>Activity</h3><p>Total activities, calls booked, briefs sent. Quick read on whether the team is engaged.</p>',
  '<h3>Recommended actions this week</h3><ul><li>3 specific actions, each named with the owner (Manoj/Nelson/Vinoth) and a concrete step.</li></ul>',
  '',
  'Be specific. Use real numbers from the JSON. Do not hedge. If a metric is zero, say zero. Keep total under 500 words.'
].join('\n');

return {
  body: {
    model: 'claude-sonnet-4-6',
    max_tokens: 1800,
    system: systemPrompt,
    messages: [{
      role: 'user',
      content: 'Stats for the last ' + (stats.period?.days || 7) + ' days (raw JSON):\n\n' + JSON.stringify(stats, null, 2)
    }],
  },
  stats,
};

const claudeResp = $input.first().json;
const stats = $('Build Claude request').first().json.stats;

if (!claudeResp || !Array.isArray(claudeResp.content)) {
  // Claude failed — fall back to a basic report so the cron still produces something
  const fallback = `<h2>Weekly pipeline report (fallback)</h2>
<p><strong>Note:</strong> AI report generation failed. Raw stats below.</p>
<pre style="background:#f5f5f5;padding:12px;border-radius:4px;font-size:11px">${JSON.stringify(stats, null, 2).replace(/</g, '&lt;')}</pre>`;
  return [{ json: { html: fallback, stats } }];
}

let html = (claudeResp.content[0]?.text || '').trim()
  .replace(/^```(?:html)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

const styled = `<!doctype html><html><body style="margin:0;padding:24px;font-family:-apple-system,Segoe UI,sans-serif;color:#111;background:#f7f7f7"><table width="640" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:8px;padding:28px;margin:0 auto"><tr><td>${html}<hr style="border:none;border-top:1px solid #eee;margin:24px 0"/><p style="font-size:11px;color:#888;margin:0">Generated automatically every Monday at 08:00 (Asia/Dubai) · <a href="https://crm.underwings.org/admin/leads" style="color:#888">Open Krayin →</a></p></td></tr></table></body></html>`;

const subject = `Underwings — weekly pipeline report (${(stats.period?.start || '').slice(0,10)} → ${(stats.period?.end || '').slice(0,10)})`;

return [{ json: { html: styled, subject, stats } }];

